SELECT * FROM works WHERE user_id = #{userId} AND deleted_at IS NULL
AND status = #{status}
ORDER BY id DESC LIMIT #{offset}, #{limit}

SELECT w.* FROM works w INNER JOIN square_posts sp ON sp.work_id = w.id
WHERE w.deleted_at IS NULL AND w.is_public = 1 AND sp.status = 1
AND sp.topic = #{topic}
ORDER BY w.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM works w INNER JOIN square_posts sp ON sp.work_id = w.id
WHERE w.deleted_at IS NULL AND w.is_public = 1 AND sp.status = 1
AND sp.topic = #{topic}
